  async function loadMobileLocale(locale){const selected=localeNames[locale]?locale:"es",read=async path=>{try{const response=await fetch(path);return response.ok?response.json():{};}catch(_){return {};}};const [base,catalog,settings]=await Promise.all([read("/locales/es.json"),read(`/locales/${selected}.json`),read("/locales/settings.json")]),messages={...base,...catalog,...(settings[selected]||{})},copy=mobileCopies[selected]||mobileCopies.es,ui={...mobileUi.es,...(mobileUi[selected]||{})},authCopy=mobileAuthCopies[selected]||mobileAuthCopies.es,appearanceCopy=appearanceCopies[selected]||appearanceCopies.es,brand=brandNames[selected]||"ARCHEON";activeLocaleMessages=messages;activeMobileCopy=copy;activeMobileUi=ui;activeAppearanceCopy=appearanceCopy;document.documentElement.lang=selected;document.documentElement.dir=selected==="ar"?"rtl":"ltr";document.querySelectorAll("[data-i18n]").forEach(node=>{if(messages[node.dataset.i18n])node.textContent=messages[node.dataset.i18n];});document.querySelectorAll("[data-i18n-placeholder]").forEach(node=>{if(messages[node.dataset.i18nPlaceholder])node.placeholder=messages[node.dataset.i18nPlaceholder];});document.querySelectorAll("[data-mobile-copy]").forEach(node=>node.textContent=copy[node.dataset.mobileCopy]||node.textContent);document.querySelectorAll("[data-mobile-ui]").forEach(node=>node.textContent=ui[node.dataset.mobileUi]||node.textContent);document.querySelectorAll("[data-mobile-auth-copy]").forEach(node=>node.textContent=authCopy[node.dataset.mobileAuthCopy]||node.textContent);document.querySelectorAll("[data-mobile-appearance]").forEach(node=>node.textContent=appearanceCopy[node.dataset.mobileAppearance]||node.textContent);document.querySelectorAll("[data-mobile-product]").forEach(node=>node.textContent=mobileProductNames[selected]||mobileProductNames.es);document.querySelectorAll("[data-brand]").forEach(node=>{node.dataset.brandTemplate=node.dataset.brandTemplate||node.textContent;node.textContent=node.dataset.brandTemplate.replace(/ARCHEON|阿尔刻翁|アルケオン|아르케온|АРХЕОН|أركيون|आर्कियोन/g,brand);});document.querySelectorAll(".mobile-language").forEach(node=>node.value=selected);if(document.getElementById("mobile-app")&&!document.getElementById("mobile-app").hidden)applySessionMode(sessionMode);localStorage.setItem("archeon_mobile_locale",selected);}
  function prepareLanguageSelectors(){document.querySelectorAll(".mobile-language").forEach(select=>{select.replaceChildren(...Object.entries(localeNames).map(([value,label])=>{const option=document.createElement("option");option.value=value;option.textContent=label;return option;}));select.addEventListener("change",()=>loadMobileLocale(select.value));});}
