  function readableError(value){
    const code=String(value||"").trim();
    const messages={session_required:"Tu sesión terminó. Entra de nuevo para continuar.",account_session_required:"ARCHEON Cloud necesita una cuenta activa.",invalid_credentials:"El correo o la contraseña no son correctos.",email_not_confirmed:"Confirma tu correo antes de iniciar sesión.",invalid_verification_code:"El código no es válido o ya venció.",auth_rate_limited:"Hubo demasiados intentos. Espera un momento y vuelve a intentarlo.",auth_request_failed:"No se pudo conectar con el servicio de cuentas.",request_failed:"No se pudo completar la solicitud. Comprueba tu conexión e inténtalo otra vez.",upload_failed:"No se pudo subir el archivo.",cloud_unavailable:"ARCHEON Cloud no está disponible en este momento.",remote_control_disabled:"El control remoto está desactivado en el dispositivo de destino.",remote_power_commands_disabled:"El permiso para apagar o reiniciar está desactivado en tu PC.",remote_confirmation_required:"Confirma esta acción en el dispositivo de destino.",remote_action_not_supported:"Ese dispositivo no admite la acción solicitada."};
    return messages[code]||code.replaceAll("_"," ")||"No se pudo completar la solicitud.";
  }
  async function request(path,payload={}){const response=await fetch(path,{method:"POST",headers:headers(),body:JSON.stringify(payload)}),value=await response.json();if(!response.ok||!value.ok)throw new Error(readableError(value.error||"request_failed"));return value;}
